// Director's Cut: audio asset naming + pure ambience-mix and music-plan maths (Agent H).
// Shared by UDCAudioSubsystem and the audio automation tests. SFX/ambience are generated by Tools/audio_gen.py,
// the music stems by Tools/music_gen.py.
#pragma once

#include "CoreMinimal.h"
#include "UObject/SoftObjectPath.h"
#include "Core/DCAudioSubsystem.h"
#include "Core/DCAssetPaths.h"

/** Test-only access to UDCAudioSubsystem's private event queue (defined in DCAudioSubsystem.cpp). */
struct FDCAudioTestAccess
{
	static int32 QueuedCount(const UDCAudioSubsystem* A, FName Sfx);
	static void ClearQueue(UDCAudioSubsystem* A);
};

namespace DCAudio
{
	/** Every canonical SFX name (DCSfx::*). */
	inline const TArray<FName>& AllSfxNames()
	{
		static const TArray<FName> Names = {
			DCSfx::Click, DCSfx::Hover, DCSfx::PanelOpen, DCSfx::PanelClose, DCSfx::Confirm, DCSfx::Error,
			DCSfx::Cash, DCSfx::SlotFill, DCSfx::MissionStart, DCSfx::MissionComplete, DCSfx::Success, DCSfx::Fail,
			DCSfx::Busted, DCSfx::LevelUp, DCSfx::BuildStart, DCSfx::RoomBuilt, DCSfx::Perk, DCSfx::Payday,
			DCSfx::GarageDoor, DCSfx::CarDepart, DCSfx::CarArrive };
		return Names;
	}

	inline FSoftObjectPath MakePath(const FString& AssetName)
	{
		return FSoftObjectPath(FString::Printf(TEXT("%s/%s.%s"), DCPaths::AudioRoot, *AssetName, *AssetName));
	}

	/** Number of round-robin variants (SFX_<Name>, SFX_<Name>_2, ...). */
	inline int32 SfxVariantCount(FName Name)
	{
		if (Name == DCSfx::Click) { return 3; }
		if (Name == DCSfx::Hover) { return 2; }
		return 1;
	}

	/** Variant 0 = SFX_<Name>; variant N>0 = SFX_<Name>_<N+1>. */
	inline FString SfxAssetName(FName Name, int32 Variant = 0)
	{
		return Variant <= 0 ? TEXT("SFX_") + Name.ToString() : FString::Printf(TEXT("SFX_%s_%d"), *Name.ToString(), Variant + 1);
	}
	inline FSoftObjectPath SfxPath(FName Name, int32 Variant = 0) { return MakePath(SfxAssetName(Name, Variant)); }

	/** Looping ambience beds, crossfaded continuously. */
	enum EBed : int32 { BedInterior = 0, BedRuralDay, BedRuralNight, BedRain, BedCount };
	inline const TCHAR* BedAssetName(int32 Bed)
	{
		static const TCHAR* Names[BedCount] = { TEXT("AMB_Interior"), TEXT("AMB_RuralDay"), TEXT("AMB_RuralNight"), TEXT("AMB_Rain") };
		return Names[FMath::Clamp(Bed, 0, (int32)BedCount - 1)];
	}

	/** Random distant one-shots (stereo, distance baked in). */
	inline const TArray<FString>& DayOneShots()   { static const TArray<FString> N = { TEXT("AMB_Crow"), TEXT("AMB_Cow"), TEXT("AMB_Tractor") }; return N; }
	inline const TArray<FString>& NightOneShots() { static const TArray<FString> N = { TEXT("AMB_Owl"), TEXT("AMB_DogBark"), TEXT("AMB_TrainHorn") }; return N; }

	// ── Music: four lounge sets x five looping stems (Tools/music_gen.py) ─────

	/** DayA/NightA open the run; DayB/NightB take over as the crew climbs the mission tiers. */
	enum EMusicSet : int32 { SetDayA = 0, SetDayB, SetNightA, SetNightB, MusicSetCount };
	/** Core (keys + bass) always plays; Groove, the two melodies and Color are layered in per 8-bar phrase. */
	enum EMusicStem : int32 { StemCore = 0, StemGroove, StemMelA, StemMelB, StemColor, MusicStemCount };

	inline const TCHAR* MusicSetName(int32 Set)
	{
		static const TCHAR* N[MusicSetCount] = { TEXT("DayA"), TEXT("DayB"), TEXT("NightA"), TEXT("NightB") };
		return N[FMath::Clamp(Set, 0, (int32)MusicSetCount - 1)];
	}
	inline const TCHAR* MusicStemName(int32 Stem)
	{
		static const TCHAR* N[MusicStemCount] = { TEXT("Core"), TEXT("Groove"), TEXT("MelA"), TEXT("MelB"), TEXT("Color") };
		return N[FMath::Clamp(Stem, 0, (int32)MusicStemCount - 1)];
	}
	inline FString MusicAssetName(int32 Set, int32 Stem) { return FString::Printf(TEXT("MUS_%s_%s"), MusicSetName(Set), MusicStemName(Stem)); }
	inline TArray<FString> AllMusicAssetNames()
	{
		TArray<FString> Out;
		for (int32 S = 0; S < MusicSetCount; ++S) { for (int32 T = 0; T < MusicStemCount; ++T) { Out.Add(MusicAssetName(S, T)); } }
		return Out;
	}
	/** Tempo of each set (matches Tools/music_gen.py); a loop is 32 bars of 4/4, a phrase 8 bars. */
	inline float MusicBpm(int32 Set)
	{
		static const float B[MusicSetCount] = { 96.f, 104.f, 82.f, 88.f };
		return B[FMath::Clamp(Set, 0, (int32)MusicSetCount - 1)];
	}
	constexpr int32 MusicLoopBars = 32;
	constexpr int32 MusicPhrasesPerLoop = 4;
	inline double MusicLoopSeconds(int32 Set) { return MusicLoopBars * 4.0 * 60.0 / MusicBpm(Set); }

	/** Every asset that must exist under /Game/DC/Audio. */
	inline TArray<FString> AllAssetNames()
	{
		TArray<FString> Out;
		for (const FName& N : AllSfxNames())
		{
			for (int32 V = 0; V < SfxVariantCount(N); ++V) { Out.Add(SfxAssetName(N, V)); }
		}
		for (int32 B = 0; B < BedCount; ++B) { Out.Add(BedAssetName(B)); }
		for (const FString& S : DayOneShots()) { Out.AddUnique(S); }
		for (const FString& S : NightOneShots()) { Out.AddUnique(S); }
		for (const FString& S : AllMusicAssetNames()) { Out.Add(S); }
		return Out;
	}

	/** Old assets that must be gone (the first score, theatre sounds, the city ambience). */
	inline const TArray<FString>& ObsoleteAssetNames()
	{
		static const TArray<FString> N = {
			TEXT("SFX_Clapper"), TEXT("SFX_Typewriter"), TEXT("SFX_Typewriter_2"), TEXT("SFX_Typewriter_3"), TEXT("SFX_Stamp"),
			TEXT("SFX_DiceRoll"), TEXT("SFX_Commit"), TEXT("SFX_CounterTick"), TEXT("SFX_StingWrap"), TEXT("SFX_StingCut"),
			TEXT("SFX_StingLevelUp"), TEXT("SFX_StingRoom"), TEXT("SFX_StingPerk"), TEXT("AMB_Projector"), TEXT("AMB_Neon"),
			TEXT("AMB_CityDay"), TEXT("AMB_CityNight"), TEXT("AMB_Siren"), TEXT("AMB_Construction"), TEXT("AMB_CarPass") };
		return N;
	}

	// ── Ambience mix (pure; unit-tested) ─────────────────────────────────────

	/** 0 at night .. 1 in full day, from the clock hour (dawn ramp 05:00-08:00, dusk ramp 18:30-21:00). */
	inline float DayFactor(float Hour)
	{
		const float H = FMath::Fmod(FMath::Fmod(Hour, 24.f) + 24.f, 24.f);
		auto Smooth = [](float A, float B, float X) { const float T = FMath::Clamp((X - A) / (B - A), 0.f, 1.f); return T * T * (3.f - 2.f * T); };
		return H < 12.f ? Smooth(5.f, 8.f, H) : 1.f - Smooth(18.5f, 21.f, H);
	}

	inline uint32 Hash2(int32 A, int32 B)
	{
		uint32 H = (uint32)A * 0x9E3779B1u ^ ((uint32)B + 0x7F4A7C15u + ((uint32)A << 6) + ((uint32)A >> 2));
		H ^= H >> 16; H *= 0x85EBCA6Bu; H ^= H >> 13; H *= 0xC2B2AE35u; H ^= H >> 16;
		return H;
	}

	/** Some days rain (never day 1). Deterministic from the run seed. */
	inline bool IsRainyDay(int32 Seed, int32 Day) { return Day >= 2 && (Hash2(Seed, Day) % 100u) < 28u; }

	/** 0..1 rain intensity at Hour on Day: a 4-10 h shower starting at a seeded hour, with 1 h ramps. */
	inline float RainAmount(int32 Seed, int32 Day, float Hour)
	{
		if (!IsRainyDay(Seed, Day)) { return 0.f; }
		const uint32 H = Hash2(Seed ^ 0x5A17, Day);
		const float Start = (float)(H % 15u) + 1.f;          // 01:00 .. 15:00
		const float Len = 4.f + (float)((H >> 8) % 7u);       // 4 .. 10 h
		const float In = FMath::Clamp(Hour - Start, 0.f, 1.f);
		const float Out = FMath::Clamp(Start + Len - Hour, 0.f, 1.f);
		return FMath::Min(In, Out);
	}

	struct FAmbienceMix { float Bed[BedCount] = { 0.f, 0.f, 0.f, 0.f }; };

	/** Target linear gains (before the Master/Ambience channel volumes) for each bed. */
	inline FAmbienceMix ComputeAmbienceMix(bool bActiveRun, float Hour, float Rain, bool bPaused)
	{
		FAmbienceMix M;
		if (!bActiveRun)
		{
			// Title: the empty warehouse at night, low.
			M.Bed[BedInterior] = 0.9f;
			M.Bed[BedRuralNight] = 0.45f;
			return M;
		}
		const float D = DayFactor(Hour);
		const float R = FMath::Clamp(Rain, 0.f, 1.f);
		const float Under = 1.f - 0.35f * R;                  // rain masks the countryside
		M.Bed[BedInterior] = 0.9f;
		M.Bed[BedRuralDay] = FMath::Sin(D * UE_HALF_PI) * Under;
		M.Bed[BedRuralNight] = FMath::Cos(D * UE_HALF_PI) * Under;
		M.Bed[BedRain] = 0.9f * R;
		if (bPaused)
		{
			for (float& G : M.Bed) { G *= 0.55f; }
		}
		return M;
	}
	// ── Music plan (pure; unit-tested) ───────────────────────────────────────

	/** Progress chapter 1..4: the unlocked mission tier (the score grows as the crew moves up). */
	inline int32 MusicChapter(int32 UnlockedTier) { return FMath::Clamp(UnlockedTier, 1, 4); }

	/** Day/night for the score with hysteresis, so dusk doesn't flip it back and forth. */
	inline bool MusicIsDay(float Hour, bool bWasDay)
	{
		const float D = DayFactor(Hour);
		return bWasDay ? D > 0.4f : D > 0.6f;
	}

	inline bool IsDaySet(int32 Set) { return Set == SetDayA || Set == SetDayB; }

	/**
	 * Which set should play next. Called at the top of every loop (and whenever day/night or title/run changes).
	 * Chapter 1 stays on the opening sets; from chapter 2 the later sets come in, and from chapter 3 they lead,
	 * with the opening tune returning now and then. A set always gets at least two passes before a change.
	 */
	inline int32 ChooseMusicSet(bool bTitle, bool bDay, int32 Chapter, int32 CurrentSet, int32 PassesOnSet, float Roll)
	{
		if (bTitle) { return SetNightA; }
		const int32 A = bDay ? SetDayA : SetNightA;
		const int32 B = bDay ? SetDayB : SetNightB;
		const int32 Ch = FMath::Clamp(Chapter, 1, 4);
		static const float PreferB[4] = { 0.f, 0.3f, 0.7f, 0.8f };
		const bool bSameTime = CurrentSet >= 0 && IsDaySet(CurrentSet) == bDay;
		if (bSameTime && (CurrentSet == A || CurrentSet == B))
		{
			if (CurrentSet == B && Ch == 1) { return A; }
			if (PassesOnSet < 2) { return CurrentSet; }
		}
		return Roll < PreferB[Ch - 1] ? B : A;
	}

	/** What one 32-bar pass carries: which melody (-1 none, 0 vibes, 1 flute) and whether the Color layer joins. */
	struct FMusicPass { int32 Melody = -1; bool bColor = false; };

	inline FMusicPass PlanMusicPass(bool bTitle, int32 Chapter, int32 PrevMelody, bool bFirstPassOnSet, float RollMelody, float RollVariant, float RollColor)
	{
		FMusicPass P;
		if (bTitle) { P.bColor = true; return P; }
		const int32 Ch = FMath::Clamp(Chapter, 1, 4);
		static const float MelodyChance[4] = { 0.5f, 0.65f, 0.8f, 0.9f };
		static const float ColorChance[4] = { 0.f, 0.45f, 0.7f, 0.9f };
		float Chance = MelodyChance[Ch - 1];
		if (PrevMelody < 0) { Chance += 0.3f; }              // after an instrumental pass the tune comes back
		if (bFirstPassOnSet && Ch < 3) { Chance = 0.f; }     // a new set opens on its groove alone
		if (RollMelody < Chance)
		{
			P.Melody = PrevMelody >= 0 ? 1 - PrevMelody : (RollVariant < 0.5f ? 0 : 1);
		}
		P.bColor = RollColor < ColorChance[Ch - 1];
		return P;
	}

	struct FMusicLayers { float Gain[MusicStemCount] = { 0.f, 0.f, 0.f, 0.f, 0.f }; };

	/** Target gain of each stem for one 8-bar phrase (0 = A, 1 = A', 2 = B / bridge, 3 = A''). */
	inline FMusicLayers ComputeMusicLayers(bool bTitle, int32 Chapter, const FMusicPass& Pass, int32 Phrase, bool bFirstPassOnSet)
	{
		FMusicLayers L;
		const int32 Ch = FMath::Clamp(Chapter, 1, 4);
		const int32 Ph = ((Phrase % MusicPhrasesPerLoop) + MusicPhrasesPerLoop) % MusicPhrasesPerLoop;
		if (bTitle)
		{
			L.Gain[StemCore] = 0.75f;
			L.Gain[StemColor] = 0.65f;
			return L;
		}
		static const float GrooveGain[4] = { 0.6f, 0.8f, 0.95f, 1.f };
		static const float ColorGain[4] = { 0.f, 0.6f, 0.8f, 1.f };
		L.Gain[StemCore] = 1.f;
		float Groove = GrooveGain[Ch - 1];
		if (bFirstPassOnSet && Ph == 0) { Groove *= 0.55f; }                  // ease in
		const bool bMelodyPhrase = Pass.Melody >= 0 && (Ch >= 3 || Ph != 2) && (Ch >= 2 || Ph != 1);
		if (Ph == 2 && Ch >= 2 && Pass.Melody >= 0) { Groove *= 0.7f; }       // the bridge breathes
		L.Gain[StemGroove] = Groove;
		if (bMelodyPhrase) { L.Gain[Pass.Melody == 0 ? StemMelA : StemMelB] = Ch == 1 ? 0.85f : 1.f; }
		if (Pass.bColor && (Ch >= 3 || Ph >= 2)) { L.Gain[StemColor] = ColorGain[Ch - 1]; }
		return L;
	}
}
